/**
 * Event arguments raised before performing a full-page redirect for authentication.
 *
 * **When raised**: Before initiating a full-page redirect to Azure AD for authentication when:
 * - Silent token acquisition fails and interaction is required
 * - Popup authentication is disabled via tenant configuration (default behavior)
 * - Popup authentication is unavailable (iframe, browser blocks) or fails
 * - The authentication flow needs to fall back to redirect flow
 * - `_ensureState()` determines a redirect is needed to establish authentication state
 *
 * **Note**: If popup authentication is not enabled by the tenant, this event is raised immediately
 * after silent authentication fails, without attempting popup first.
 *
 * **NAA (Nested App Authentication) Exception**:
 * This event is **NOT raised** when running in Teams, Outlook, or mobile webviews with NAA support.
 * NAA uses the host application's native broker and does not perform browser redirects.
 *
 * **Use cases**:
 * - Cancel the automatic redirect and handle authentication manually
 * - Show custom UI or save application state before navigation
 * - Implement custom redirect logic or error handling
 * - Prevent redirect in specific scenarios (e.g., iframe contexts, recent redirect attempts)
 *
 * **How to use**: Subscribe to `AadTokenProvider.onBeforeRedirectEvent` and call `cancel()` to prevent
 * the automatic redirect. The `redirectUrl` property contains the destination URL that would be navigated to.
 *
 * @example
 * ```typescript
 * aadTokenProvider.onBeforeRedirectEvent.add(observer, (args: BeforeRedirectEventArgs) => {
 *   // Save application state before redirect
 *   saveCurrentState();
 *
 *   // Or cancel and handle manually
 *   args.cancel();
 *   window.location.href = args.redirectUrl;
 * });
 * ```
 *
 * @public
 */
export declare class BeforeRedirectEventArgs extends SPEventArgs implements IBeforeRedirectEventArgs {
    /**
     * The id of the instance generating the event.
     */
    configuration?: IAadTokenProviderConfiguration;
    /**
     * The url of the page to redirect to if automatic redirect is cancelled
     */
    redirectUrl: string;
    /**
     * Call this method if the redirect should be cancelled because it is being handled by code in the cancelling class.
     */
    cancel: () => void;
    constructor(redirectUrl: string, cancel: () => void, configuration?: IAadTokenProviderConfiguration | undefined);
}

